<template>
	<div class="vue-player--youtube" :style="styles">
		<div ref="container"/>
	</div>
</template>

<script>
	import { getSDK, parseEndTime, parseStartTime } from "../../utils";
	import { canPlay } from "../../patterns";
	import { playerMixin } from "../../mixins/player";
	import { youtubeConfigProps } from "../../props/youtubeConfig";

	const SDK_URL = "https://www.youtube.com/iframe_api";
	const SDK_GLOBAL = "YT";
	const SDK_GLOBAL_READY = "onYouTubeIframeAPIReady";
	const MATCH_PLAYLIST = /[?&](?:list|channel)=([a-zA-Z0-9_-]+)/;
	const MATCH_USER_UPLOADS = /user\/([a-zA-Z0-9_-]+)\/?/;
	const MATCH_NOCOOKIE = /youtube-nocookie\.com/;
	const NOCOOKIE_HOST = "https://www.youtube-nocookie.com";

	export default {
		// [META]
		displayName: "YouTube",
		canPlay: canPlay.youtube,
		// [/META]

		mixins: [playerMixin],

		props: {
			config: youtubeConfigProps(),
		},

		computed: {
			styles() {
				return {
					display: this.display,
					width: "100%",
					height: "100%",
				};
			},
		},

		methods: {
			/**
			 * @inheritDoc
			 * @override
			 * @playerHook play
			 */
			play() {
				this.callPlayer("playVideo");
			},

			/**
			 * @inheritDoc
			 * @override
			 * @playerHook pause
			 */
			pause() {
				this.callPlayer("pauseVideo");
			},

			/**
			 * @inheritDoc
			 * @override
			 * @playerHook stop
			 */
			stop() {
				if (!document.body.contains(this.callPlayer("getIframe"))) return;
				this.callPlayer("stopVideo");
			},

			/**
			 * @inheritDoc
			 * @override
			 * @playerHook seekTo
			 */
			seekTo(amount) {
				this.callPlayer("seekTo", amount);
				if (!this.playing) {
					this.pause();
				}
			},

			/**
			 * @inheritDoc
			 * @override
			 * @playerHook setVolume
			 */
			setVolume(fraction) {
				this.callPlayer("setVolume", fraction * 100);
			},

			/**
			 * @inheritDoc
			 * @override
			 * @playerHook mute
			 */
			mute() {
				this.callPlayer("mute");
			},

			/**
			 * @inheritDoc
			 * @override
			 * @playerHook unmute
			 */
			unmute() {
				this.callPlayer("unmute");
			},

			/**
			 * @inheritDoc
			 * @override
			 * @playerHook setPlaybackRate
			 */
			setPlaybackRate(rate) {
				this.callPlayer("setPlaybackRate", rate);
			},

			/**
			 * @inheritDoc
			 * @override
			 * @playerHook setLoop
			 */
			setLoop(loop) {
				this.callPlayer("setLoop", loop);
			},

			/**
			 * @inheritDoc
			 * @override
			 * @playerHook getDuration
			 */
			getDuration() {
				return this.callPlayer("getDuration");
			},

			/**
			 * @inheritDoc
			 * @override
			 * @playerHook getCurrentTime
			 */
			getCurrentTime() {
				return this.callPlayer("getCurrentTime");
			},

			/**
			 * @inheritDoc
			 * @override
			 * @playerHook getSecondsLoaded
			 */
			getSecondsLoaded() {
				return this.callPlayer("getVideoLoadedFraction") * this.getDuration();
			},

			async load(url, isReady) {
				try {
					const { playing, muted, playsinline, controls, loop, config, onError } = this;
					const { playerVars, embedOptions } = config;
					const id = this.getID(url);
					if (isReady) {
						if (MATCH_PLAYLIST.test(url) || MATCH_USER_UPLOADS.test(url) || url instanceof Array) {
							this.player.loadPlaylist(this.parsePlaylist(url));
							return;
						}
						this.player.cueVideoById({
							videoId: id,
							startSeconds: parseStartTime(url) || playerVars.start,
							endSeconds: parseEndTime(url) || playerVars.end,
						});
						return;
					}
					const YT = await getSDK(SDK_URL, SDK_GLOBAL, SDK_GLOBAL_READY, YT => YT.loaded);
					if (!this.container) return;
					this.player = new YT.Player(this.container, {
						width: "100%",
						height: "100%",
						videoId: id,
						playerVars: {
							autoplay: playing ? 1 : 0,
							mute: muted ? 1 : 0,
							controls: controls ? 1 : 0,
							start: parseStartTime(url),
							end: parseEndTime(url),
							origin: window.location.origin,
							playsinline: playsinline ? 1 : 0,
							...this.parsePlaylist(url),
							...playerVars,
						},
						events: {
							onReady: () => {
								if (loop) {
									this.player.setLoop(true); // Enable playlist looping
								}
								this.onReady();
							},
							onPlaybackRateChange: event => this.onPlaybackRateChange(event.data),
							onStateChange: this.onStateChange,
							onError: event => onError(event.data),
						},
						host: MATCH_NOCOOKIE.test(url) ? NOCOOKIE_HOST : undefined,
						...embedOptions,
					});

					if (embedOptions.events) {
						console.warn("Using `embedOptions.events` will likely break things. Use ReactPlayer’s callback props instead, eg onReady, onPlay, onPause");
					}
				} catch (e) {
					this.onError(e);
				}
			},

			parsePlaylist(url) {
				if (url instanceof Array) {
					return {
						listType: "playlist",
						playlist: url.map(this.getID).join(","),
					};
				}
				if (MATCH_PLAYLIST.test(url)) {
					const [, playlistId] = url.match(MATCH_PLAYLIST);
					return {
						listType: "playlist",
						list: playlistId.replace(/^UC/, "UU"),
					};
				}
				if (MATCH_USER_UPLOADS.test(url)) {
					const [, username] = url.match(MATCH_USER_UPLOADS);
					return {
						listType: "user_uploads",
						list: username,
					};
				}
				return {};
			},

			onStateChange(event) {
				const { data } = event;
				const {
					onPlay,
					onPause,
					onBuffer,
					onBufferEnd,
					onEnded,
					onReady,
					loop,
					config: { playerVars, onUnstarted },
				} = this;
				const { UNSTARTED, PLAYING, PAUSED, BUFFERING, ENDED, CUED } = window[SDK_GLOBAL].PlayerState;
				if (data === UNSTARTED) onUnstarted();
				if (data === PLAYING) {
					onPlay();
					onBufferEnd();
				}
				if (data === PAUSED) onPause();
				if (data === BUFFERING) onBuffer();
				if (data === ENDED) {
					const isPlaylist = !!this.callPlayer("getPlaylist");
					// Only loop manually if not playing a playlist
					if (loop && !isPlaylist) {
						if (playerVars.start) {
							this.seekTo(playerVars.start);
						} else {
							this.play();
						}
					}
					onEnded();
				}
				if (data === CUED) onReady();
			},
		},
	};
</script>
